// Few-shot assembler: instructions, balanced examples, negative, live input
function buildFewShot({ instructions, examples, negative, input }) {
  const messages = [{ role: "system", content: instructions }];
  for (const ex of examples) {
    messages.push({ role: "user", content: "Input: " + ex.in });
    messages.push({ role: "assistant", content: "Output: " + ex.out });
  }
  messages.push({ role: "user", content: "Do NOT do this: " + negative.bad + " (" + negative.why + ")" });
  messages.push({ role: "user", content: "Input: " + input });
  return messages;
}
