function auditExamples(examples, labels) {
  const counts = {};
  for (const ex of examples) counts[ex.label] = (counts[ex.label] || 0) + 1;
  const missing = labels.filter((l) => !counts[l]);
  const total = examples.length;
  const share = Object.entries(counts).map(([l, n]) => l + ':' + Math.round((n / total) * 100) + '%');
  return { coverage: (labels.length - missing.length) + '/' + labels.length, missing, balance: share.join(' ') };
}
const labels = ['billing', 'shipping', 'returns'];
